DO $p3c_do$
DECLARE
  v_data jsonb := $p3c_json${"standard":{"code":"FLL-TP-RHIZOM-2023","title_de":"Technische Prüfbestimmungen zur Bestimmung der Rhizomfestigkeit von Gewässerabdichtungen","title_en":"Technical Test Specifications for the Determination of Rhizome Resistance of Water Body Sealings","version":"Dezember 2023"},"worksheets":[{"code":"FLLTP-RHZ-01","title_de":"Auftragsregistrierung","title_en":"Test order registration","phase":1,"archetype":"registration","order_index":1,"description":"Stammdaten des Prüfauftrags: Prüfinstitut, Auftraggeber, Berichtsnummer, Prüfungsstart- und -enddatum. Vorbereitung des späteren Prüfberichts."},{"code":"FLLTP-RHZ-02","title_de":"Produkt- und Herstellerangaben","title_en":"Product and manufacturer data","phase":1,"archetype":"data_collection","order_index":2,"description":"Verbindliche Herstellerangaben: Produktbezeichnung, Abdichtungsart, Fügetechnik, wachstumshemmende Wirkstoffe (Kennzeichnung erforderlich), Schutzschicht bei Mehrschichtprodukten, ggf. zusätzliche Lage unter Beschichtungen."},{"code":"FLLTP-RHZ-03","title_de":"Geltungsbereichsprüfung","title_en":"Scope applicability check","phase":1,"archetype":"verification","order_index":3,"description":"Prüfung, ob das eingereichte Produkt unter den Geltungsbereich des Verfahrens fällt (Einzelprodukt, nicht Abdichtungssystem; Bitumen-/Kunststoff-/Elastomerbahn, Flüssigabdichtung, Gussasphalt oder GUP-Beschichtung)."},{"code":"FLLTP-RHZ-04","title_de":"Standort & Gewächshausbedingungen","title_en":"Site & greenhouse conditions","phase":2,"archetype":"data_collection","order_index":4,"description":"Dokumentation der Gewächshausbedingungen: Heizung, Lüftung, Temperatursollwerte tagsüber/nachts, Lüftungsschwelle, Temperatur-obergrenze."},{"code":"FLLTP-RHZ-05","title_de":"Prüf- und Kontrollgefäße & Apparatur","title_en":"Test and control vessels & apparatus","phase":2,"archetype":"data_collection","order_index":5,"description":"Spezifikation und Stückzahl der Prüfgefäße (8/Abdichtung) und Kontrollgefäße (3/Prüfung), Widerlager aus Polystyrol, ggf. Trennlage, Abdichtungsmaterialbedarf."},{"code":"FLLTP-RHZ-06","title_de":"Vegetationstragschicht-Eingangsprüfung","title_en":"Substrate inspection","phase":2,"archetype":"verification","order_index":6,"description":"Eingangsprüfung der Vegetationstragschicht (gewaschener Sand 0-4 mm) gegen die Anforderungen aus Tab. 1: pH (CaCl2), Salz (H2O/CaSO4), N, P2O5, K2O, CaCO3 (Bestimmung nach VDLUFA-Vorgaben)."},{"code":"FLLTP-RHZ-07","title_de":"Düngemittel & Gießwasser-Eingangsprüfung","title_en":"Fertilizer & irrigation water inspection","phase":2,"archetype":"verification","order_index":7,"description":"Eingangsprüfung Düngemittel (Mehrnährstoffdünger mit Spurenelementen) und Gießwasser gemäß Tab. 2 (Ammonium, Eisen, P_ges, Härte, Leitfähigkeit, Mangan, Nitrat, ortho-Phosphat, pH, Säurekapazität)."},{"code":"FLLTP-RHZ-08","title_de":"Testpflanzen-Qualität","title_en":"Test plant quality check","phase":2,"archetype":"verification","order_index":8,"description":"Verifizierung der Testpflanzenart (Phragmites australis - Schilf), Containergröße (9x9), gleichmäßige Pflanzenqualität."},{"code":"FLLTP-RHZ-09","title_de":"Einbau der Abdichtung in Prüfgefäße","title_en":"Installation of sealing in test vessels","phase":3,"archetype":"data_collection","order_index":9,"description":"Einbau in zwei Prüfmustern (45° versetzt). Bei Bahnen: 4 Wand-Eck-Nähte, 2 Boden-Eck-Nähte, 1 mittige T-Naht. Bei Flüssigabdichtungen/Gussasphalt/GUP: Arbeitsunterbrechungsfuge mit Mindest-Zeitabstand 12 h zwischen den Arbeitsschritten. Untere VTS (20 ±5) mm, obere VTS (150 ±5) mm."},{"code":"FLLTP-RHZ-10","title_de":"Vorbereitung der Kontrollgefäße","title_en":"Preparation of control vessels","phase":3,"archetype":"data_collection","order_index":10,"description":"Einbau in den 3 wasserdichten Kontrollgefäßen ohne Widerlager und ohne Abdichtung: untere VTS (20 ±5) mm, Standrohr, obere VTS (150 ±5) mm, Bepflanzung analog Prüfgefäße."},{"code":"FLLTP-RHZ-11","title_de":"Bepflanzung","title_en":"Planting","phase":3,"archetype":"data_collection","order_index":11,"description":"Einsetzen von 8 Schilfpflanzen pro Prüfgefäß (800 x 800 mm). Erste Düngegabe unmittelbar nach Bepflanzung."},{"code":"FLLTP-RHZ-12","title_de":"Pflege & Düngungsprotokoll","title_en":"Care & fertilization log","phase":4,"archetype":"data_collection","order_index":12,"description":"Laufende Pflege: Wasserstand 20 mm über bis 50 mm unter VTS-Oberfläche, monatliche Düngung (5 g in 20 l Wasser pro Gefäß), Entfernen von Fremdwuchs/Algen/abgestorbenen Pflanzenteilen. Ersatz abgestorbener Pflanzen nur in den ersten 3 Monaten. Halmschnitt im grünen Zustand nicht zulässig. Schädlingsbekämpfung bei Bedarf."},{"code":"FLLTP-RHZ-13","title_de":"Wuchsleistung Zwischenauswertung 6 Monate","title_en":"Growth assessment - 6 month interim","phase":4,"archetype":"calculation","order_index":13,"description":"1. Zwischenauswertung: Halmanzahl pro Prüfgefäß (P1..P8) und Kontrollgefäß (K1..K3); Sollwert Ø ≥ 80 Halme/Gefäß; relative Bestandsdichte (Prüf/Kontroll) ≥ 80 %."},{"code":"FLLTP-RHZ-14","title_de":"Wuchsleistung Zwischenauswertung 12 Monate","title_en":"Growth assessment - 12 month interim","phase":4,"archetype":"calculation","order_index":14,"description":"2. Zwischenauswertung: Sollwert Ø ≥ 120 Halme/Gefäß; relative Bestandsdichte ≥ 80 %."},{"code":"FLLTP-RHZ-15","title_de":"Wuchsleistung Zwischenauswertung 18 Monate","title_en":"Growth assessment - 18 month interim","phase":4,"archetype":"calculation","order_index":15,"description":"3. Zwischenauswertung: Sollwert Ø ≥ 160 Halme/Gefäß; relative Bestandsdichte ≥ 80 %."},{"code":"FLLTP-RHZ-16","title_de":"Wuchsleistung Endauswertung 24 Monate","title_en":"Growth assessment - 24 month final","phase":5,"archetype":"calculation","order_index":16,"description":"Endauswertung Wuchsleistung: Sollwert Ø ≥ 160 Halme/Gefäß; relative Bestandsdichte ≥ 80 %. Voraussetzung für gültiges Prüfergebnis."},{"code":"FLLTP-RHZ-17","title_de":"Rhizomeindringung & -durchdringung Erfassung","title_en":"Rhizome ingress & penetration recording","phase":5,"archetype":"data_collection","order_index":17,"description":"Erfassung ein- und durchgedrungener Rhizome je Gefäß, getrennt nach Fläche und Naht (bahnenartig) bzw. Fläche und Arbeitsunterbrechungsfuge (nicht bahnenartig). Maximale Eindringtiefe in Überlappungsbereichen. Fotografische Dokumentation. Sondertatbestände aus §3.9 (Poren, wachstumshemmende Wirkstoffe, Mehrschichtprodukte, Nahtversiegelungen) sind aufzuführen, aber nicht als Eindringung zu werten."},{"code":"FLLTP-RHZ-18","title_de":"Bewertung Rhizomfestigkeit (Gate)","title_en":"Rhizome resistance verdict (gate)","phase":5,"archetype":"verification","order_index":18,"description":"Gate: Produkt gilt als rhizomfest, wenn in allen 8 Prüfgefäßen nach 24 Monaten KEINE Rhizomeindringungen UND KEINE Rhizomdurchdringungen festgestellt werden UND die Wuchsleistung der Testpflanzen (§3.7) durchgehend ausreichend war. Andernfalls: nicht rhizomfest oder vorzeitiger Abbruch."},{"code":"FLLTP-RHZ-19","title_de":"Prüfbericht Erstellung","title_en":"Test report compilation","phase":6,"archetype":"summary","order_index":19,"description":"Vollständiger Prüfbericht in doppelter Ausführung (nur bei rhizomfestem Produkt). Pflichtinhalte: Herstellerangaben, Vorbereitungsdetails, Auswertungsergebnisse, zusammenfassende Bewertung. Pflichtformulierungen einschließlich Gültigkeitsdauer-Klausel (10 Jahre). Rückstellproben-Hinweis."},{"code":"FLLTP-RHZ-20","title_de":"Umschreibung & Verlängerung","title_en":"Reissue & extension of certificate","phase":6,"archetype":"registration","order_index":20,"description":"Verlängerungen in 5-Jahres-Schritten möglich, sofern: Prüfgrundlagen unverändert, Produkt im aktuellen Lieferprogramm, neue Rückstellmuster hinterlegt, eidesstattliche Identitätserklärung des Herstellers. Umschreibung nur zur Fehlerkorrektur/Datenergänzung; nicht bei Markennamenänderung ohne Neuprüfung."},{"code":"FLLTP-RHZ-21","title_de":"Konformitäts-Gesamtbescheinigung","title_en":"Overall conformity summary","phase":6,"archetype":"verification","order_index":21,"description":"Abschließende Konformitätsbewertung: Geltungsbereich erfüllt, alle Eingangsprüfungen bestanden, Wuchsleistung an allen vier Auswertungspunkten ausreichend, Endauswertung ohne Rhizom-ein-/-durchdringung. Verdict: rhizomfest / nicht rhizomfest / vorzeitig abgebrochen."}],"sections":[{"ws_code":"FLLTP-RHZ-01","code":"A","title_de":"Zweck und Kontext","order_index":1,"parent_code":null},{"ws_code":"FLLTP-RHZ-01","code":"B","title_de":"Eingangsdaten","order_index":2,"parent_code":null},{"ws_code":"FLLTP-RHZ-01","code":"C","title_de":"Worksheet-spezifischer Inhalt","order_index":3,"parent_code":null},{"ws_code":"FLLTP-RHZ-01","code":"D","title_de":"Abgeleitete Werte / Berechnungen","order_index":4,"parent_code":null},{"ws_code":"FLLTP-RHZ-01","code":"F","title_de":"Ergebnis-Zusammenfassung","order_index":5,"parent_code":null},{"ws_code":"FLLTP-RHZ-01","code":"J","title_de":"Output-Übergabe","order_index":6,"parent_code":null},{"ws_code":"FLLTP-RHZ-01","code":"K","title_de":"Notizen und Annahmen","order_index":7,"parent_code":null},{"ws_code":"FLLTP-RHZ-01","code":"L","title_de":"Freigabe","order_index":8,"parent_code":null},{"ws_code":"FLLTP-RHZ-01","code":"M","title_de":"Workflow-Verknüpfung","order_index":9,"parent_code":null},{"ws_code":"FLLTP-RHZ-02","code":"A","title_de":"Zweck und Kontext","order_index":1,"parent_code":null},{"ws_code":"FLLTP-RHZ-02","code":"B","title_de":"Eingangsdaten","order_index":2,"parent_code":null},{"ws_code":"FLLTP-RHZ-02","code":"C","title_de":"Worksheet-spezifischer Inhalt","order_index":3,"parent_code":null},{"ws_code":"FLLTP-RHZ-02","code":"D","title_de":"Abgeleitete Werte / Berechnungen","order_index":4,"parent_code":null},{"ws_code":"FLLTP-RHZ-02","code":"F","title_de":"Ergebnis-Zusammenfassung","order_index":5,"parent_code":null},{"ws_code":"F